#include <iostream>
#include <memory>

struct TreeNode {
    int data{0};
    std::unique_ptr<TreeNode> left{nullptr};
    std::unique_ptr<TreeNode> right{nullptr};

    explicit TreeNode(int val) : data(val), left(nullptr), right(nullptr) {}
};

int main() {
    // Manually constructing a small BST: root 47, left 25, right 77
    auto root = std::make_unique<TreeNode>(47);
    root->left = std::make_unique<TreeNode>(25);
    root->right = std::make_unique<TreeNode>(77);

    std::cout << "Root: " << root->data << "\n";
    std::cout << "Left child: " << root->left->data << "\n";
    std::cout << "Right child: " << root->right->data << "\n";
    std::cout << "Is left leaf? " << (root->left->left == nullptr && root->left->right == nullptr ? "Yes" : "No") << "\n";
    return 0;
}

#include <iostream>
#include <vector>

struct TreeNode {
    int data;
    TreeNode* left;
    TreeNode* right;
    explicit TreeNode(int val) : data(val), left(nullptr), right(nullptr) {}
};

// Using reference-to-pointer (idiomatic modern C++ equivalent to C's TreeNodePtr*)
void insertNode(TreeNode*& treePtr, int value) {
    if (treePtr == nullptr) {
        treePtr = new TreeNode(value);
    } else if (value < treePtr->data) {
        insertNode(treePtr->left, value);
    } else if (value > treePtr->data) {
        insertNode(treePtr->right, value);
    } else {
        std::cout << "dup ";
    }
}

void preOrder(const TreeNode* treePtr) {
    if (treePtr != nullptr) {
        std::cout << treePtr->data << " ";
        preOrder(treePtr->left);
        preOrder(treePtr->right);
    }
}

void inOrder(const TreeNode* treePtr) {
    if (treePtr != nullptr) {
        inOrder(treePtr->left);
        std::cout << treePtr->data << " ";
        inOrder(treePtr->right);
    }
}

void postOrder(const TreeNode* treePtr) {
    if (treePtr != nullptr) {
        postOrder(treePtr->left);
        postOrder(treePtr->right);
        std::cout << treePtr->data << " ";
    }
}

void freeTree(TreeNode* treePtr) {
    if (treePtr != nullptr) {
        freeTree(treePtr->left);
        freeTree(treePtr->right);
        delete treePtr;
    }
}

int main() {
    TreeNode* rootPtr = nullptr;
    // Data from Fig 12.20 in textbook: 6, 7, 4, 12, 7(dup), 2, 2(dup), 5, 7(dup), 11
    const std::vector<int> values = {6, 7, 4, 12, 7, 2, 2, 5, 7, 11};

    std::cout << "Inserting values: ";
    for (int val : values) {
        std::cout << val << " ";
        insertNode(rootPtr, val);
    }
    std::cout << "\n";

    std::cout << "Preorder:  ";
    preOrder(rootPtr);
    std::cout << "\n";

    std::cout << "Inorder:   ";
    inOrder(rootPtr);
    std::cout << "\n";

    std::cout << "Postorder: ";
    postOrder(rootPtr);
    std::cout << "\n";

    freeTree(rootPtr);
    return 0;
}
